const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const REPO='GuibsFred/TSSR_Cours', DATA='data/custom.json';
let catalog=[],custom={pages:[],quizzes:[],commands:[]},token='',sha='',section='accueil',current=null,editing=false,dirty=false;
const labels={accueil:['⌂','Accueil'],cours:['▤','Cours'],tp:['⚒','Travaux pratiques'],fiches:['✦','Fiches de révision'],quiz:['✓','QCM interactifs'],commandes:['⌘','Commandes'],glossaire:['☷','Glossaire'],cheats:['▧','Cheatsheets']};
const toast=s=>{let t=$('#toast');t.textContent=s;t.style.display='block';setTimeout(()=>t.style.display='none',4500)};
const storageKey='tssr-draft-v4';
const oldStorageKey='viking-tssr-draft-v3';
let activeFolder='',commandEnvironment='',commandCategory='',commandLetter='';
const folderParts=x=>String(x||'').split('/').map(v=>v.trim()).filter(Boolean);
const folderMatches=(p,path)=>!path||folderParts(p.category).join(' / ').toLowerCase().startsWith(path.toLowerCase());
const folderIcon='📁';
// Petits pictogrammes liés au sujet : repérables sans alourdir la navigation.
function courseIcon(item){
 const name=String(typeof item==='string'?item:(item?.title||item?.category||'')).toLowerCase();
 if(/microsoft 365|office|outlook|word|excel|collaboratif/.test(name))return '🗂️';
 if(/réseau|reseau|wifi|wi-fi|cisco|routeur|switch|adressage/.test(name))return '🌐';
 if(/linux|gnu|bash|shell/.test(name))return '🐧';
 if(/windows|microsoft|powershell|active directory/.test(name))return '🖥️';
 if(/sécurit|securit|pare-feu|firewall/.test(name))return '🛡️';
 if(/virtualis|serveur|cloud/.test(name))return '🖧';
 if(/sauvegarde|restauration/.test(name))return '💾';
 if(/itil|glpi|gestion de parc/.test(name))return '🛠️';
 if(/stage|entreprise|professionnelle/.test(name))return '🎓';
 if(/messagerie|mail/.test(name))return '✉️';
 return '📘';
}

const moduleNumber=x=>{let m=String(x||'').match(/^(\d{1,2})\s*[—–-]/);return m?+m[1]:999};
const sortModule=(a,b)=>moduleNumber(a.category)-moduleNumber(b.category)||String(a.category).localeCompare(String(b.category),'fr',{numeric:true})||String(a.title).localeCompare(String(b.title),'fr',{numeric:true});
const cleanKey=x=>[x.kind,x.category,x.title].map(v=>String(v||'').trim().toLocaleLowerCase('fr')).join('|');
const dirtyIds=new Set();
let remoteSnapshot=new Map();
const rootCategory=x=>folderParts(x)[0]||'Sans catégorie';
const stripFrontmatter=t=>String(t).replace(/^---\s*\r?\n[\s\S]*?\r?\n---\s*\r?\n/,'');
const safeImage=u=>/^data:image\/(png|jpeg|gif|webp);base64,/i.test(u)||/^https:\/\//i.test(u);

const saveLocal=(id)=>{if(id)dirtyIds.add(id);localStorage.setItem(storageKey,JSON.stringify({savedAt:Date.now(),data:custom,dirtyIds:[...dirtyIds]}));dirty=true;toast('Enregistré sur cet appareil. Publie sur GitHub pour synchroniser.')};
function all(){let unique=new Map();for(const x of catalog){unique.set('base:'+x.file,{...x,id:'base:'+x.file,readonly:true})}for(const p of custom.pages){if(!p||!p.id)continue;const base=p.id.startsWith('base:');if(base){unique.delete(p.id)}else{for(const [id,x] of unique){if(x.readonly&&cleanKey(x)===cleanKey(p)){unique.delete(id);break}}}unique.set(p.id,{...p,readonly:false})}return [...unique.values()].sort(sortModule)}

// Les fiches liées sont virtuelles : aucune duplication de cours ni de fiche à publier.
const revisionId=id=>'revision:'+id;
const sourceId=id=>id.slice('revision:'.length);
function revisionNotes(id){return custom.pages.find(p=>p.kind==='fiches'&&p.revisionSource===id)}
function revisionCourses(){return all().filter(p=>p.kind==='cours')}
function isBlueColor(value){
 if(!value)return false;
 const c=document.createElement('span');c.style.color=value;
 if(!c.style.color)return false;
 document.body.appendChild(c);let rgb=getComputedStyle(c).color;c.remove();
 const nums=rgb.match(/[\d.]+/g)?.slice(0,3).map(Number);
 if(!nums||nums.length<3)return false;
 const [r,g,b]=nums, max=Math.max(r,g,b),min=Math.min(r,g,b);
 return b>r*1.16&&b>g*1.07&&b-r>=24&&max-min>=35;
}
function extractBlue(html){
 const root=document.createElement('div');root.innerHTML=DOMPurify.sanitize(html||'');
 const found=[],seen=new Set();
 function walk(el,insideBlue=false){
  if(el.nodeType===Node.TEXT_NODE){const t=el.textContent.replace(/\s+/g,' ').trim();if(insideBlue&&t&&!seen.has(t)){seen.add(t);found.push(t)}return}
  if(el.nodeType!==Node.ELEMENT_NODE||['SCRIPT','STYLE','IMG','SVG'].includes(el.tagName))return;
  const style=el.getAttribute('style')||'';
  const declared=style.match(/(?:^|;)\s*color\s*:\s*([^;]+)/i)?.[1];
  const blue=el.hasAttribute('data-revision-blue') || (declared?isBlueColor(declared):insideBlue) || (el.getAttribute('color')?isBlueColor(el.getAttribute('color')):false);
  // Un lien bleu par défaut n'est pas un passage marqué pour les révisions.
  for(const child of el.childNodes)walk(child,blue);
 }
 for(const child of root.childNodes)walk(child,false);
 return found;
}
async function revisionSourceHtml(course){
 if(!course)return '';
 if(!course.readonly)return course.html||'';
 try{const r=await fetch(course.file);if(!r.ok)return '';return marked.parse(stripFrontmatter(await r.text()))}catch{return ''}
}
async function showRevision(id){
 const course=revisionCourses().find(x=>x.id===id),notes=revisionNotes(id),v=$('#view');
 if(!course){v.innerHTML=header('Fiche introuvable','Le cours associé n’existe plus.');return}
 v.innerHTML=header('Fiche de révision — '+course.title,course.category,`<div class="actions"><button class="btn" data-id="${esc(id)}">📘 Voir le cours</button><button class="btn primary" data-revision-edit="${esc(id)}">✎ Mes notes</button></div>`)+`<article class="article"><h2>🔵 À retenir dans ce cours</h2><p class="muted">Les passages écrits en bleu dans le cours apparaissent ici après son enregistrement.</p><div id="revisionExtract" class="revision-extract">Chargement…</div><h2>📝 Mes notes personnelles</h2><div class="content">${DOMPurify.sanitize(notes?.html||'<p class="muted">Aucune note pour le moment. Clique sur « Mes notes » pour compléter cette fiche.</p>')}</div></article>`;
 const html=await revisionSourceHtml(course);const dest=$('#revisionExtract');if(!dest)return;
 const extracts=extractBlue(html);dest.innerHTML=extracts.length?`<ul>${extracts.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`:'<p class="muted">Aucun passage bleu pour le moment. Ouvre le cours, colore une phrase en bleu et enregistre.</p>';
}
function editRevisionNotes(id){
 const course=revisionCourses().find(x=>x.id===id),old=revisionNotes(id);if(!course)return;
 modal('Mes notes — '+course.title,`<p>Ces notes restent indépendantes des passages bleus du cours.</p><div class="toolbar"><button type="button" data-note-cmd="bold"><b>G</b></button><button type="button" data-note-cmd="italic"><i>I</i></button><button type="button" data-note-cmd="insertUnorderedList">☷ Liste</button></div><div id="revisionNoteEditor" class="editor" contenteditable="true">${DOMPurify.sanitize(old?.html||'')}</div><div class="actions"><button type="button" class="btn" id="cancelRevisionNotes">Annuler</button><button type="button" class="btn primary" id="saveRevisionNotes">Enregistrer les notes</button></div>`);
 document.querySelectorAll('[data-note-cmd]').forEach(b=>b.onclick=()=>{$('#revisionNoteEditor').focus();document.execCommand(b.dataset.noteCmd,false,null)});
 $('#cancelRevisionNotes').onclick=()=>$('#modal').close();$('#saveRevisionNotes').onclick=()=>{
 const obj={id:old?.id||'notes-'+id,kind:'fiches',revisionSource:id,title:'Notes — '+course.title,category:course.category,html:DOMPurify.sanitize($('#revisionNoteEditor').innerHTML),updatedAt:new Date().toISOString()};
 const i=custom.pages.findIndex(x=>x.id===obj.id);if(i>=0)custom.pages[i]=obj;else custom.pages.push(obj);
 saveLocal(obj.id);$('#modal').close();showRevision(id);
 };
}
const normKind=x=>x==='cours'?'cours':x;
function nav(){let q=$('#search').value.toLowerCase().trim();$('#mainNav').innerHTML=Object.entries(labels).map(([k,[ico,label]])=>`<button class="navlink ${section===k?'active':''}" data-sec="${k}"><span class="sym">${ico}</span>${label}</button>`).join('');
const courses=all().filter(x=>x.kind==='cours'&&(!q||(x.title+' '+x.category).toLowerCase().includes(q)));
const roots=[...new Set(courses.map(x=>rootCategory(x.category)))].sort((a,b)=>moduleNumber(a)-moduleNumber(b)||a.localeCompare(b,'fr',{numeric:true}));
$('#modules').innerHTML=roots.map(root=>{let group=courses.filter(x=>rootCategory(x.category)===root);let base=group.find(x=>x.id.startsWith('base:'))||group[0];return `<div class="foldergroup"><button class="module folderhead" data-folder="${esc(root)}"><span class="folder-symbol">${courseIcon(root)}</span><span>${esc(root)}</span></button><button class="module childmodule" data-id="${esc(base.id)}">📘 Cours</button><button class="module childmodule" data-quiz-category="${esc(root)}">☑️ QCM</button></div>`}).join('');}

