const imageEditor=$('#docEditor'), imageControls=$('#imageControls'), imageWidth=$('#imageWidth');
let selectedCourseImage=null,lastSavedCourseId=p?.id||null;
function selectCourseImage(img){
  if(selectedCourseImage)selectedCourseImage.classList.remove('course-image-selected');
  selectedCourseImage=img&&imageEditor.contains(img)?img:null;
  imageControls.classList.toggle('inactive',!selectedCourseImage);
  if(!selectedCourseImage){$('#imageWidthValue').textContent='Clique sur une image';return;}
  selectedCourseImage.classList.add('course-image-selected');
  const containerWidth=imageEditor.clientWidth-40;
  const percent=selectedCourseImage.style.width.endsWith('%')?parseFloat(selectedCourseImage.style.width):Math.min(100,Math.round((selectedCourseImage.getBoundingClientRect().width/Math.max(containerWidth,1))*100));
  imageWidth.value=Math.max(10,Math.min(100,percent||100));$('#imageWidthNumber').value=imageWidth.value;$('#imageWidthValue').textContent=imageWidth.value+' %';
}
imageEditor.addEventListener('pointerdown',e=>{const img=e.target.closest?.('img');if(img){selectCourseImage(img);e.preventDefault()}},true);imageEditor.addEventListener('click',e=>{const img=e.target.closest?.('img');if(img)selectCourseImage(img)});selectCourseImage(null);
imageWidth.addEventListener('input',()=>{if(!selectedCourseImage)return;selectedCourseImage.style.width=imageWidth.value+'%';selectedCourseImage.style.maxWidth='100%';selectedCourseImage.style.height='auto';$('#imageWidthNumber').value=imageWidth.value;$('#imageWidthValue').textContent=imageWidth.value+' %'});
$('#imageWidthNumber').addEventListener('change',e=>{imageWidth.value=Math.max(10,Math.min(100,Number(e.target.value)||100));imageWidth.dispatchEvent(new Event('input'))});
function alignCourseImage(side){if(!selectedCourseImage)return;selectedCourseImage.style.display='block';selectedCourseImage.style.marginTop='12px';selectedCourseImage.style.marginBottom='12px';selectedCourseImage.style.marginLeft=side==='left'?'0':side==='center'?'auto':'auto';selectedCourseImage.style.marginRight=side==='right'?'0':side==='center'?'auto':'auto'}
$('#imageAlignLeft').onclick=()=>alignCourseImage('left');$('#imageAlignCenter').onclick=()=>alignCourseImage('center');$('#imageAlignRight').onclick=()=>alignCourseImage('right');
