$('#blueRevision').onmousedown=e=>e.preventDefault();
$('#blueRevision').onclick=()=>{
 const selection=window.getSelection();
 if(!selection||selection.isCollapsed||!imageEditor.contains(selection.anchorNode)||!imageEditor.contains(selection.focusNode)){
  toast('Sélectionne d’abord le passage du cours à mettre en bleu.');return;
 }
 try{
  const range=selection.getRangeAt(0),marker=document.createElement('span');
  marker.style.color='#1769d2';marker.setAttribute('data-revision-blue','true');
  marker.appendChild(range.extractContents());range.insertNode(marker);
  selection.removeAllRanges();
  toast('Passage bleu marqué pour la fiche de révision.');
 }catch(e){document.execCommand('foreColor',false,'#1769d2');toast('Texte coloré en bleu.');}
};
