function commandEditor(id){const old=(custom.commands||[]).find(x=>x.id===id);modal(old?'Modifier une commande':'Ajouter une commande',`<div class="commandform"><label>Nom de la commande<input class="formfield" id="cName" value="${esc(old?.name||'')}" placeholder="Get-Service" required></label><label>Environnement<input class="formfield" id="cEnv" list="cEnvs" value="${esc(old?.environment||'PowerShell')}"><datalist id="cEnvs">${['PowerShell','Linux / Bash','Windows CMD','Cisco IOS','Réseaux','Autre'].map(x=>`<option value="${x}">`).join('')}</datalist></label><label>Catégorie<input class="formfield" id="cCat" value="${esc(old?.category||'')}" placeholder="Services, fichiers, réseau…"></label><label>Thème<input class="formfield" id="cTheme" value="${esc(old?.theme||'')}" placeholder="Diagnostic"></label><label>Description<textarea class="formfield" id="cDesc" rows="3">${esc(old?.description||'')}</textarea></label><label>Syntaxe<textarea class="formfield" id="cSyntax" rows="2" placeholder="Get-Service -Name Spooler">${esc(old?.syntax||'')}</textarea></label><label>Exemple<textarea class="formfield" id="cExample" rows="3">${esc(old?.example||'')}</textarea></label><label>Notes / précautions<textarea class="formfield" id="cNotes" rows="3">${esc(old?.notes||'')}</textarea></label><label>Mots-clés (séparés par des virgules)<input class="formfield" id="cTags" value="${esc((old?.tags||[]).join(', '))}"></label><div class="actions"><button type="button" class="btn primary" id="saveCommand">Enregistrer</button><button type="button" class="btn" id="cancelCommand">Annuler</button></div></div>`);$('#cancelCommand').onclick=()=>$('#modal').close();$('#saveCommand').onclick=()=>{const name=$('#cName').value.trim();if(!name){toast('Le nom est obligatoire.');return}const obj={id:old?.id||'cmd-'+Date.now(),name,environment:$('#cEnv').value.trim()||'Autre',category:$('#cCat').value.trim()||'Divers',theme:$('#cTheme').value.trim(),description:$('#cDesc').value.trim(),syntax:$('#cSyntax').value.trim(),example:$('#cExample').value.trim(),notes:$('#cNotes').value.trim(),tags:$('#cTags').value.split(',').map(x=>x.trim()).filter(Boolean)};custom.commands=(custom.commands||[]).filter(x=>x.id!==obj.id);custom.commands.push(obj);saveLocal('cmd:'+obj.id);$('#modal').close();goto('commandes')}}
function commandDetail(id){let x=(custom.commands||[]).find(x=>x.id===id);if(!x)return;modal(x.name,`<p><span class="pill">${esc(x.environment)}</span> ${esc(x.category)} · ${esc(x.theme||'Général')}</p><p>${esc(x.description)}</p>${x.syntax?`<h3>Syntaxe</h3><pre class="commandcode"><code>${esc(x.syntax)}</code></pre><button class="btn" id="copySyntax">Copier la syntaxe</button>`:''}${x.example?`<h3>Exemple</h3><pre class="commandcode"><code>${esc(x.example)}</code></pre><button class="btn" id="copyExample">Copier l’exemple</button>`:''}${x.notes?`<p class="commandnote">⚠️ ${esc(x.notes)}</p>`:''}<div class="actions"><button class="btn primary" id="detailEdit">Modifier</button><button class="btn" id="detailClose">Fermer</button></div>`);if($('#copySyntax'))$('#copySyntax').onclick=()=>navigator.clipboard.writeText(x.syntax).then(()=>toast('Syntaxe copiée'));if($('#copyExample'))$('#copyExample').onclick=()=>navigator.clipboard.writeText(x.example).then(()=>toast('Exemple copié'));$('#detailEdit').onclick=()=>{$('#modal').close();commandEditor(id)};$('#detailClose').onclick=()=>$('#modal').close()}
function importCommands(){let input=$('#cmdImportFile');input.onchange=async()=>{try{const parsed=JSON.parse(await input.files[0].text());if(!Array.isArray(parsed)||parsed.length>2000)throw Error('Le fichier doit contenir un tableau de 2000 commandes maximum.');if(!parsed.every(x=>x&&typeof x.name==='string'&&x.name.trim()))throw Error('Chaque commande doit avoir un nom.');let added=0;for(const x of parsed){let name=x.name.trim().slice(0,160),environment=String(x.environment||'Autre').slice(0,80);let old=(custom.commands||[]).find(y=>y.name.toLowerCase()===name.toLowerCase()&&y.environment.toLowerCase()===environment.toLowerCase());if(old)continue;let id='cmd-'+Date.now()+'-'+added;let obj={id,name,environment,category:String(x.category||'Divers').slice(0,100),theme:String(x.theme||'').slice(0,100),description:String(x.description||'').slice(0,4000),syntax:String(x.syntax||'').slice(0,4000),example:String(x.example||'').slice(0,8000),notes:String(x.notes||'').slice(0,4000),tags:Array.isArray(x.tags)?x.tags.filter(y=>typeof y==='string').slice(0,20):[]};custom.commands.push(obj);dirtyIds.add('cmd:'+id);added++}if(added)saveLocal();toast(added+' commande(s) importée(s), doublons ignorés.');render()}catch(e){toast('Import impossible : '+e.message)}};input.click()}
function exportCommands(){const data=JSON.stringify(custom.commands||[],null,2),blob=new Blob([data],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='tssr-commandes.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}

function playQuiz(id){let q=custom.quizzes.find(x=>x.id===id);if(!q)return;let i=0,score=0;const next=()=>{if(i>=q.questions.length){modal('Résultat',`<h2>${score} / ${q.questions.length}</h2><p>QCM terminé !</p><button class="btn" type="button" id="closeQuiz">Fermer</button>`);$('#closeQuiz').onclick=()=>$('#modal').close();return}let z=q.questions[i];modal(q.title,`<p class="muted">Question ${i+1} / ${q.questions.length}</p><h3>${esc(z.question)}</h3>${z.answers.map((x,j)=>`<label class="quizoption"><input type="radio" name="ans" value="${j}">${esc(x)}</label>`).join('')}<button type="button" class="btn primary" id="qNext">Valider</button><p id="qFeedback"></p>`);$('#qNext').onclick=()=>{let val=$('input[name="ans"]:checked');if(!val){toast('Choisis une réponse.');return}if(+val.value===z.correct)score++;$('#qFeedback').textContent=(+val.value===z.correct?'Bonne réponse !':'Bonne réponse : '+z.answers[z.correct]);$('#qNext').textContent='Suivant';$('#qNext').onclick=()=>{i++;next()}}};next()}
function githubModal(autoPublish=false){modal('Connexion GitHub',`<p>Pour publier depuis le site, crée un <b>jeton GitHub à accès limité</b> au dépôt <code>${REPO}</code>, avec la permission <b>Contents: Read and write</b>. Il ne sera gardé que dans la mémoire de cet onglet, jamais dans les fichiers du site ni dans le stockage local.</p><p><a target="_blank" rel="noopener" href="https://github.com/settings/personal-access-tokens/new">Créer un jeton GitHub ↗</a></p><label>Jeton d'accès (fine-grained)<input type="password" id="gitToken" class="formfield" placeholder="github_pat_..."></label><div class="actions"><button type="button" class="btn primary" id="setToken">Connecter</button><button type="button" class="btn" id="forgetToken">Déconnecter</button></div><p class="editorhelp">⚠️ Cette méthode demande un jeton personnel. Ne l'utilise pas sur un ordinateur partagé. Ne donne jamais ce jeton à quelqu'un. Une connexion OAuth serait préférable pour une utilisation publique à grande échelle.</p>`);$('#setToken').onclick=()=>{token=$('#gitToken').value.trim();$('#gitToken').value='';$('#modal').close();toast('Connexion prête.');if(autoPublish)publish()};$('#forgetToken').onclick=()=>{token='';$('#modal').close();toast('Jeton oublié')}}
const b64utf8=s=>btoa(Array.from(new TextEncoder().encode(s),c=>String.fromCharCode(c)).join(''));
const fromB64=b=>new TextDecoder().decode(Uint8Array.from(atob(b.replace(/\s/g,'')),c=>c.charCodeAt(0)));
async function publish(){if(!token){githubModal(true);toast('Connecte GitHub : le brouillon est sauvegardé et la publication reprendra.');return false}if(!dirtyIds.size){toast('Aucune modification locale à publier.');return}try{const url=`https://api.github.com/repos/${REPO}/contents/${DATA}`;const head={Authorization:'Bearer '+token,Accept:'application/vnd.github+json','X-GitHub-Api-Version':'2022-11-28'};
for(let attempt=0;attempt<2;attempt++){let old=await fetch(url+'?t='+Date.now(),{headers:head,cache:'no-store'});let live={pages:[],quizzes:[],cheats:[],commands:[]},remoteSha=null;if(old.ok){let j=await old.json();remoteSha=j.sha;live=JSON.parse(fromB64(j.content))}else if(old.status!==404)throw Error('Lecture GitHub impossible : '+old.status);if(!Array.isArray(live.pages))live.pages=[];if(!Array.isArray(live.quizzes))live.quizzes=[];if(!Array.isArray(live.cheats))live.cheats=[];if(!Array.isArray(live.commands))live.commands=[];
for(const id of [...dirtyIds].filter(x=>!x.startsWith('quiz:')&&!x.startsWith('cheat:')&&!x.startsWith('cmd:'))){let original=remoteSnapshot.get(id),now=live.pages.find(x=>x.id===id);if(original&&now&&JSON.stringify(now)!==original){throw Error('Ce cours a été modifié ailleurs. Recharge le site avant de publier pour éviter un écrasement.')}}
// Migrate legacy duplicates from the previous site without touching unrelated notes.
const baseTitles=new Map(catalog.filter(x=>x.kind==='cours').map(x=>[x.title.toLocaleLowerCase('fr'),x]));
const editedBaseNames=new Set([...dirtyIds].filter(id=>id.startsWith('base:')).map(id=>catalog.find(c=>'base:'+c.file===id)?.title.toLocaleLowerCase('fr')).filter(Boolean));
if(editedBaseNames.size){live.pages=live.pages.filter(p=>!editedBaseNames.has(String(p.title||'').toLocaleLowerCase('fr'))||dirtyIds.has(p.id))}
for(const id of [...dirtyIds].filter(x=>!x.startsWith('quiz:')&&!x.startsWith('cheat:')&&!x.startsWith('cmd:'))){let mine=custom.pages.find(x=>x.id===id);let ix=live.pages.findIndex(x=>x.id===id);if(mine){if(ix>=0)live.pages[ix]=mine;else live.pages.push(mine)}else if(ix>=0)live.pages.splice(ix,1)}
for(const id of dirtyIds){if(id.startsWith('quiz:')){let key=id.slice(5),mine=custom.quizzes.find(x=>x.id===key);live.quizzes=live.quizzes.filter(x=>x.id!==key);if(mine)live.quizzes.push(mine)}if(id.startsWith('cmd:')){let key=id.slice(4),mine=(custom.commands||[]).find(x=>x.id===key);live.commands=live.commands.filter(x=>x.id!==key);if(mine)live.commands.push(mine)}if(id.startsWith('cheat:')){let key=id.slice(6),mine=(custom.cheats||[]).find(x=>x.id===key);live.cheats=live.cheats.filter(x=>x.id!==key);if(mine)live.cheats.push(mine)}}
const result=await fetch(url,{method:'PUT',headers:{...head,'Content-Type':'application/json'},body:JSON.stringify({message:'TSSR : sauvegarde des cours',content:b64utf8(JSON.stringify(live,null,2)),branch:'main',...(remoteSha?{sha:remoteSha}:{})})});if(result.status===409&&attempt===0)continue;if(!result.ok){let error=await result.json().catch(()=>({}));throw Error(error.message||'Erreur '+result.status)}
custom=live;remoteSnapshot=new Map(live.pages.map(p=>[p.id,JSON.stringify(p)]));dirtyIds.clear();localStorage.removeItem(storageKey);localStorage.removeItem(oldStorageKey);dirty=false;toast('✓ Enregistré sur GitHub. La publication du site peut prendre quelques minutes.');render();return true}
}catch(e){toast('Publication impossible : '+e.message);return false}}
async function init(){try{let r=await fetch('data/catalog.json');if(r.ok)catalog=await r.json();r=await fetch(DATA+'?v='+Date.now(),{cache:'no-store'});if(r.ok)custom=await r.json()}catch(e){console.warn(e)}if(!Array.isArray(custom.pages))custom.pages=[];if(!Array.isArray(custom.quizzes))custom.quizzes=[];if(!Array.isArray(custom.cheats))custom.cheats=[];if(!Array.isArray(custom.commands))custom.commands=[];remoteSnapshot=new Map(custom.pages.map(p=>[p.id,JSON.stringify(p)]));try{const d=JSON.parse(localStorage.getItem(storageKey)||'null');if(d?.data&&Array.isArray(d.dirtyIds)&&d.dirtyIds.length){for(const id of d.dirtyIds){let p=d.data.pages?.find(x=>x.id===id);if(id.startsWith('quiz:')){let x=d.data.quizzes?.find(q=>q.id===id.slice(5));custom.quizzes=custom.quizzes.filter(q=>q.id!==id.slice(5));if(x)custom.quizzes.push(x);dirtyIds.add(id);continue}if(id.startsWith('cmd:')){let x=d.data.commands?.find(q=>q.id===id.slice(4));custom.commands=custom.commands.filter(q=>q.id!==id.slice(4));if(x)custom.commands.push(x);dirtyIds.add(id);continue}if(id.startsWith('cheat:')){let x=d.data.cheats?.find(q=>q.id===id.slice(6));custom.cheats=custom.cheats.filter(q=>q.id!==id.slice(6));if(x)custom.cheats.push(x);dirtyIds.add(id);continue}if(p){custom.pages=custom.pages.filter(x=>x.id!==id);custom.pages.push(p);dirtyIds.add(id)}else{custom.pages=custom.pages.filter(x=>x.id!==id);dirtyIds.add(id)}}dirty=true;toast('Modifications locales non publiées récupérées.')}}catch(e){console.warn('Brouillon ignoré',e)}section=decodeURIComponent(location.hash.slice(1)||'accueil');if(section.startsWith('folder=')){activeFolder=decodeURIComponent(section.slice(7));section='cours'}if(section.startsWith('page=')){current=section.slice(5);section=current.startsWith('revision:')?'fiches':(all().find(x=>x.id===current)?.kind||'cours')}render()}
document.addEventListener('click',e=>{let b=e.target.closest('[data-sec],[data-id],[data-revision],[data-revision-edit],[data-folder],[data-edit],[data-delete],[data-quiz],[data-quiz-category],[data-cheat-category],[data-open-cheat],[data-edit-cheat],[data-delete-cheat],[data-edit-quiz],[data-delete-quiz],[data-cmd-letter],[data-view-command],[data-edit-command],[data-delete-command],#newCommand,#importCommands,#exportCommands,#newCheat,#newPage,#newQuiz,#connectBtn,#newBtn,#themeBtn,#menuBtn');if(!b)return;if(b.hasAttribute('data-cmd-letter')){commandLetter=b.dataset.cmdLetter;render()}else if(b.dataset.revisionEdit)editRevisionNotes(b.dataset.revisionEdit);else if(b.dataset.revision)goto('fiches',revisionId(b.dataset.revision));else if(b.dataset.viewCommand)commandDetail(b.dataset.viewCommand);else if(b.dataset.editCommand)commandEditor(b.dataset.editCommand);else if(b.dataset.deleteCommand){if(confirm('Supprimer cette commande ?')){custom.commands=custom.commands.filter(x=>x.id!==b.dataset.deleteCommand);saveLocal('cmd:'+b.dataset.deleteCommand);render()}}else if(b.id==='newCommand')commandEditor();else if(b.id==='importCommands')importCommands();else if(b.id==='exportCommands')exportCommands();else if(b.dataset.sec){goto(b.dataset.sec);$('#sidebar').classList.remove('show')}else if(b.hasAttribute('data-folder')){gotoFolder(b.dataset.folder);$('#sidebar').classList.remove('show')}else if(b.dataset.id){let p=all().find(x=>x.id===b.dataset.id);goto(p?.kind||'cours',b.dataset.id)}else if(b.dataset.edit)editor(b.dataset.edit);else if(b.dataset.delete){if(confirm('Supprimer ce document ?')){custom.pages=custom.pages.filter(x=>x.id!==b.dataset.delete);saveLocal(b.dataset.delete);goto(section)}}else if(b.hasAttribute('data-quiz-category')){activeFolder=b.dataset.quizCategory;section='quiz';current=null;render()}else if(b.hasAttribute('data-cheat-category')){section='cheats';$('#search').value=b.dataset.cheatCategory;render()}else if(b.dataset.openCheat)openCheat(b.dataset.openCheat);else if(b.dataset.editCheat)newCheat(b.dataset.editCheat);else if(b.dataset.deleteCheat){if(confirm('Supprimer cette cheatsheet ?')){custom.cheats=custom.cheats.filter(x=>x.id!==b.dataset.deleteCheat);saveLocal('cheat:'+b.dataset.deleteCheat);render()}}else if(b.dataset.editQuiz)newQuiz(b.dataset.editQuiz);else if(b.dataset.deleteQuiz){if(confirm('Supprimer ce QCM ?')){custom.quizzes=custom.quizzes.filter(x=>x.id!==b.dataset.deleteQuiz);saveLocal('quiz:'+b.dataset.deleteQuiz);render()}}else if(b.dataset.quiz)playQuiz(b.dataset.quiz);else if(b.id==='newCheat')newCheat();else if(b.id==='newQuiz')newQuiz();else if(['newPage','newBtn'].includes(b.id))editor(null);else if(b.id==='connectBtn')githubModal();else if(b.id==='themeBtn'){document.body.classList.toggle('dark');localStorage.setItem('tssr-theme',document.body.classList.contains('dark')?'dark':'light')}else if(b.id==='menuBtn')document.body.classList.toggle('sidebar-collapsed')});
$('#search').addEventListener('input',()=>{current=null;render()});if((localStorage.getItem('tssr-theme')||localStorage.getItem('viking-theme'))==='dark')document.body.classList.add('dark');init();
